from __future__ import annotations

from pathlib import Path


SUPPORTED_FORMATS = (
    "tar", "zip", "bz", "bz2", "bz3", "gz", "lz4", "xz", "lzma",
    "lz", "sz", "zst", "rar", "7z", "br",
)

ALIASES = {
    "tgz": ("tar", "gz"), "tbz": ("tar", "bz"),
    "tbz2": ("tar", "bz2"), "tlz4": ("tar", "lz4"),
    "txz": ("tar", "xz"), "tlzma": ("tar", "lzma"),
    "tsz": ("tar", "sz"), "tzst": ("tar", "zst"),
    "tlz": ("tar", "lz"), "cbt": ("tar",), "cbz": ("zip",),
    "epub": ("zip",), "cb7": ("7z",), "cbr": ("rar",),
}

_KNOWN = frozenset(SUPPORTED_FORMATS) | frozenset(ALIASES)


class UnsupportedFormat(ValueError):
    """Raised when a suffix is not one of the documented formats."""


def canonical_format(extension: str) -> str:
    """Return the canonical format name for a suffix, case-insensitively."""
    extension = extension.strip().lower().lstrip(".")
    if extension in SUPPORTED_FORMATS:
        return extension
    if extension in ALIASES:
        return ALIASES[extension][0]
    raise UnsupportedFormat(extension)


def parse_formats(value: str) -> list[str]:
    """Parse a `--format` value or dotted suffix chain into canonical names.

    Examples: ``tar.gz`` -> ``["tar", "gz"]`` and ``tgz`` -> ``["tar"]``.
    The order is the order in which suffixes are applied to a file.
    """
    value = value.strip().lower()
    if value.startswith("."):
        value = value[1:]
    parts = value.split(".")
    if not value or any(not part for part in parts):
        raise UnsupportedFormat(value)
    result: list[str] = []
    for part in parts:
        if part in ALIASES:
            result.extend(ALIASES[part])
        else:
            result.append(canonical_format(part))
    return result


def detect_format(path: str | Path) -> list[str]:
    """Infer canonical format names from a filename's trailing suffix chain."""
    name = Path(path).name
    if "." not in name:
        return []
    # Dotfiles are not interpreted as extension-only names.
    if name.startswith(".") and name.count(".") == 1:
        return []
    parts = name.split(".")[1:]
    # Walk backward from the final extension; stop at the first ordinary name.
    chain: list[str] = []
    for ext in reversed(parts):
        if ext.lower() not in _KNOWN:
            break
        chain.append(canonical_format(ext))
    return list(reversed(chain))

"""Formatting helpers for Ouch-style terminal output."""


def format_size(size: int | float) -> str:
    """Return a fixed-width, base-1000 byte size (without surrounding quotes)."""
    value = float(size)
    units = ("B", "kiB", "MiB", "GiB", "TiB")
    index = 0
    while value >= 1000 and index < len(units) - 1:
        value /= 1000
        index += 1
    return f"{value:6.2f} {units[index]:>3}"
